ALTER TABLE members ADD COLUMN muted_until bigint NOT NULL DEFAULT 0;
ALTER TABLE channels ADD COLUMN private bigint NOT NULL DEFAULT 0;
ALTER TABLE messages ADD COLUMN reply_to text;
ALTER TABLE messages ADD COLUMN client_id text;
CREATE UNIQUE INDEX message_idempotency ON messages("user",client_id) WHERE client_id IS NOT NULL;
CREATE TABLE accounts(id text PRIMARY KEY REFERENCES users(id),email text UNIQUE NOT NULL,password text NOT NULL,admin boolean NOT NULL DEFAULT false,disabled boolean NOT NULL DEFAULT false,created bigint NOT NULL);
CREATE TABLE sessions(id text PRIMARY KEY,"user" text NOT NULL REFERENCES users(id),created bigint NOT NULL,expires bigint NOT NULL,agent text NOT NULL);
CREATE INDEX sessions_user ON sessions("user");
CREATE TABLE access_invites(hash text PRIMARY KEY,email text,creator text,expires bigint NOT NULL,used_by text,revoked boolean NOT NULL DEFAULT false,created bigint NOT NULL);
CREATE TABLE resets(hash text PRIMARY KEY,"user" text NOT NULL,expires bigint NOT NULL,used boolean NOT NULL DEFAULT false);
CREATE TABLE login_limits(key text PRIMARY KEY,hits bigint NOT NULL,expires bigint NOT NULL);
CREATE TABLE app_settings(key text PRIMARY KEY,value text NOT NULL);
CREATE TABLE roles(id text PRIMARY KEY,server text NOT NULL,name text NOT NULL,color text NOT NULL,manage bigint NOT NULL DEFAULT 0,moderate bigint NOT NULL DEFAULT 0,post bigint NOT NULL DEFAULT 1,speak bigint NOT NULL DEFAULT 1);
CREATE TABLE member_roles(server text NOT NULL,"user" text NOT NULL,role text NOT NULL REFERENCES roles(id) ON DELETE CASCADE,PRIMARY KEY(server,"user",role));
CREATE TABLE channel_access(channel text NOT NULL,subject text NOT NULL,kind text NOT NULL,PRIMARY KEY(channel,subject,kind));
CREATE TABLE bans(server text NOT NULL,"user" text NOT NULL,reason text NOT NULL,expires bigint,PRIMARY KEY(server,"user"));
CREATE TABLE reports(id text PRIMARY KEY,message text NOT NULL,channel text NOT NULL,reporter text NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'open',created bigint NOT NULL);
CREATE TABLE polls(id text PRIMARY KEY,channel text NOT NULL,creator text NOT NULL,question text NOT NULL,options text NOT NULL,expires bigint NOT NULL,closed bigint NOT NULL DEFAULT 0,created bigint NOT NULL);
CREATE TABLE votes(poll text NOT NULL REFERENCES polls(id) ON DELETE CASCADE,"user" text NOT NULL,choice bigint NOT NULL,PRIMARY KEY(poll,"user"));
CREATE TABLE events(id text PRIMARY KEY,channel text NOT NULL,creator text NOT NULL,title text NOT NULL,description text NOT NULL,starts bigint NOT NULL,created bigint NOT NULL);
CREATE TABLE rsvps(event text NOT NULL REFERENCES events(id) ON DELETE CASCADE,"user" text NOT NULL,response text NOT NULL,PRIMARY KEY(event,"user"));
CREATE TABLE notifications(id text PRIMARY KEY,"user" text NOT NULL,channel text NOT NULL,message text,content text NOT NULL,created bigint NOT NULL,seen bigint NOT NULL DEFAULT 0);
CREATE TABLE custom_emojis(id text PRIMARY KEY,server text NOT NULL,name text NOT NULL,value text NOT NULL,UNIQUE(server,name));
CREATE TABLE audit(id bigserial PRIMARY KEY,actor text NOT NULL,action text NOT NULL,detail text NOT NULL,created bigint NOT NULL);
